    // V4 on the system clipboard: both copies (VIDEO_COPY_FRAME_TO_CLIPBOARD,
    // VIDEO_COPY_SUBBED_FRAME_TO_CLIPBOARD; legacy RendererVideo::SaveFrame put
    // a wxBitmapDataObject there) read back by another process. Windows:
    // tools/winix/clipboard-image.ps1 (System.Windows.Forms.Clipboard's
    // GetImage, the device-independent bitmap other programs paste); X11:
    // xclip's image/png. The owner hands the image over through its own
    // event loop, so the reader is waited for without blocking it. Skipped
    // where the clipboard is this process's own (offscreen) or no reader
    // exists; winix task v4-clipboard-window fails on that skip.
    void videoSnapshotsReachTheSystemClipboard()
    {
        const QString platform = QGuiApplication::platformName();
        const QString out = QDir(QDir::tempPath()).filePath(QStringLiteral("hikari-clipboard-readback.png"));
        QString program;
        QStringList arguments;
#ifdef Q_OS_WIN
        if (platform != QLatin1String("windows"))
            QSKIP(qPrintable(QStringLiteral("the %1 platform's clipboard is this process's own").arg(platform)));
        program = QStringLiteral("powershell.exe");
        arguments = {QStringLiteral("-NoProfile"), QStringLiteral("-STA"), QStringLiteral("-ExecutionPolicy"),
                     QStringLiteral("Bypass"), QStringLiteral("-File"),
                     QDir::toNativeSeparators(QStringLiteral(HIKARI_UI_SOURCE_DIR "/../../tools/winix/clipboard-image.ps1")),
                     QDir::toNativeSeparators(out)};
#else
        if (platform != QLatin1String("xcb"))
            QSKIP(qPrintable(QStringLiteral("the %1 platform's clipboard is not X11's").arg(platform)));
        program = QStandardPaths::findExecutable(QStringLiteral("xclip"));
        if (program.isEmpty())
            QSKIP("no xclip to read the X11 clipboard from another process");
        arguments = {QStringLiteral("-selection"), QStringLiteral("clipboard"), QStringLiteral("-t"),
                     QStringLiteral("image/png"), QStringLiteral("-o")};
#endif
        restartWithoutSound();
        QTemporaryDir &folder = testFolder();
        QVERIFY(folder.isValid());
        QVERIFY(v4Open(folder));
        const auto &session = application->video().session();
        const QImage plain = cpuReference(*session.lastFrame(), nullptr);
        const QImage subbed = cpuReference(*session.lastFrame(), session.lastOverlay().get());
        QVERIFY(plain != subbed);
        auto *root = engine->rootObjects().first();
        for (const auto &[action, expected] : {std::pair{"VIDEO_COPY_SUBBED_FRAME_TO_CLIPBOARD", subbed},
                                               std::pair{"VIDEO_COPY_FRAME_TO_CLIPBOARD", plain}}) {
            QGuiApplication::clipboard()->clear();
            QTest::qWait(60); // VideoBox::OnAccelerator drops the same action within 50 ms (VideoBox.cpp:1137)
            QVERIFY(QMetaObject::invokeMethod(root, "runVideoHotkey", Q_ARG(QVariant, QString::fromLatin1(action))));
            QTRY_VERIFY(sameImage(QGuiApplication::clipboard()->image(), expected));
            QFile::remove(out);
            QProcess reader;
#ifndef Q_OS_WIN
            reader.setStandardOutputFile(out);
#endif
            reader.start(program, arguments);
            QVERIFY2(reader.waitForStarted(10000), qPrintable(reader.errorString()));
            QTRY_VERIFY_WITH_TIMEOUT(reader.state() == QProcess::NotRunning, 60000);
            const QString said = QString::fromLocal8Bit(reader.readAllStandardOutput() + reader.readAllStandardError()).trimmed();
            qInfo().noquote() << action << "read back by" << QFileInfo(program).fileName() << said;
            QVERIFY2(reader.exitStatus() == QProcess::NormalExit && reader.exitCode() == 0, qPrintable(said));
            const QImage read(out);
            QVERIFY2(!read.isNull(), qPrintable(QStringLiteral("%1 wrote no image").arg(program)));
            if (!sameImage(read, expected)) {
                // Kept beside the read-back for a comparison (the copied frame and its format).
                expected.save(out + QStringLiteral(".expected.png"));
                qInfo().noquote() << action << "copied frame format" << int(expected.format()) << "hasAlpha"
                                  << expected.hasAlphaChannel() << "saved to" << out + QStringLiteral(".expected.png");
            }
            QVERIFY2(sameImage(read, expected),
                     qPrintable(QStringLiteral("%1: read back %2x%3, copied %4x%5")
                                    .arg(QLatin1String(action))
                                    .arg(read.width())
                                    .arg(read.height())
                                    .arg(expected.width())
                                    .arg(expected.height())));
        }
        QFile::remove(out);
    }

    // The clipboard read-back is compared by its pixels: a PNG that names
    // sRGB (what .NET writes from the Windows clipboard) loads with that
    // colour space, which QImage's == compares too. Legacy copies the frame
    // as bare RGB24 (RendererVideo::SaveFrame), so only the pixels count.
    void clipboardReadBackIsComparedByItsPixels()
    {
        QImage frame(8, 6, QImage::Format_RGB888);
        for (int y = 0; y < frame.height(); ++y)
            for (int x = 0; x < frame.width(); ++x)
                frame.setPixel(x, y, qRgb(x * 30, y * 40, (x + y) * 15));
        QImage tagged = frame;
        tagged.setColorSpace(QColorSpace(QColorSpace::SRgb));
        QByteArray png;
        QBuffer buffer(&png);
        QVERIFY(buffer.open(QIODevice::WriteOnly));
        QVERIFY(tagged.save(&buffer, "PNG"));
        QImage read = QImage::fromData(png, "PNG");
        QVERIFY(!read.isNull());
        QVERIFY(read.colorSpace().isValid());
        QVERIFY(!frame.colorSpace().isValid());
        // The comparison that failed on Windows with equal pixels.
        QVERIFY(read.convertToFormat(QImage::Format_RGB888) != frame);
        QVERIFY(sameImage(read, frame));
        QVERIFY(sameImage(frame, read));
        QVERIFY(sameImage(read.convertToFormat(QImage::Format_ARGB32), frame));
        QImage changed = read;
        changed.setPixel(3, 2, qRgb(1, 2, 3));
        QVERIFY(!sameImage(changed, frame));
        QVERIFY(!sameImage(read.copy(0, 0, 7, 6), frame));
    }

    // The Script properties YCbCr matrix reaches the video's colours: the
    // shown frame is decoded again with it (legacy ProviderFFMS2::SetColorSpace
    // and Render while paused).
    void scriptPropertiesMatrixRecoloursTheVideo()
    {
        restartWithoutSound();
        QTemporaryDir &folder = testFolder();
        QVERIFY(folder.isValid());
        QFile::copy(QStringLiteral(HIKARI_MEDIA_FIXTURES "/color709.mkv"), folder.filePath(QStringLiteral("clip.mkv")));
        QFile f(folder.filePath(QStringLiteral("clip.ass")));
        QVERIFY(f.open(QIODevice::WriteOnly));
        f.write("[Script Info]\nScriptType: v4.00+\nPlayResX: 320\nPlayResY: 240\nYCbCr Matrix: TV.709\n\n[Events]\n"
                "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n"
                "Dialogue: 0,0:00:00.00,0:00:00.10,Default,,0,0,0,,x\n");
        f.close();
        QVERIFY(application->openFile(f.fileName()));
        application->video().openVideo(folder.filePath(QStringLiteral("clip.mkv")));
        const auto &session = application->video().session();
        QTRY_VERIFY_WITH_TIMEOUT(session.lastFrame(), 20000);
        QCOMPARE(session.colourMatrix().applied(), std::string("TV.709"));
        // The top-left patch (Y' 180, Cb 60, Cr 200, limited range) as
        // R, G, B; its red saturates under both matrices, so all three
        // channels are compared with each matrix's equations.
        auto pixel = [&] {
            const auto &fr = *session.lastFrame();
            const std::byte *p = fr.bgra.data() + std::size_t(fr.height / 4) * fr.stride + std::size_t(fr.width / 4) * 4;
            return std::array<int, 3>{std::to_integer<int>(p[2]), std::to_integer<int>(p[1]), std::to_integer<int>(p[0])};
        };
        auto expected = [](double kr, double kb) {
            const double y = (180 - 16) / 219.0, pb = (60 - 128) / 224.0, pr = (200 - 128) / 224.0;
            const double r = y + 2 * (1 - kr) * pr, b = y + 2 * (1 - kb) * pb, g = (y - kr * r - kb * b) / (1 - kr - kb);
            auto code = [](double v) { return int(std::lround(std::clamp(v, 0.0, 1.0) * 255)); };
            return std::array<int, 3>{code(r), code(g), code(b)};
        };
        auto near = [](const std::array<int, 3> &a, const std::array<int, 3> &b) {
            for (int k = 0; k < 3; ++k)
                if (std::abs(a[k] - b[k]) > 3)
                    return false;
            return true;
        };
        const auto bt709 = expected(0.2126, 0.0722), bt601 = expected(0.299, 0.114); // 255,167,47 and 255,159,54
        QVERIFY(!near(bt709, bt601));
        QVERIFY(near(pixel(), bt709));
        // Script properties (Y3): the matrix changed to TV.601 (index 1).
        auto *root = engine->rootObjects().first();
        auto *dialog = root->findChild<QObject *>(QStringLiteral("scriptPropertiesDialog"));
        QVERIFY(QMetaObject::invokeMethod(root->findChild<QObject *>(QStringLiteral("assProperties")), "triggered"));
        QTRY_VERIFY(dialog->property("visible").toBool());
        auto *matrix = dialogItem("scriptPropertiesDialog", "propMatrix");
        QCOMPARE(matrix->property("currentText").toString(), QStringLiteral("TV.709"));
        matrix->setProperty("currentIndex", 1);
        QCOMPARE(matrix->property("currentText").toString(), QStringLiteral("TV.601"));
        QVERIFY(QMetaObject::invokeMethod(dialog, "accept"));
        QTRY_VERIFY_WITH_TIMEOUT(near(pixel(), bt601), 10000);
        QCOMPARE(session.colourMatrix().applied(), std::string("TV.601"));
        auto *edited = application->files().session(*application->workspace().editingTarget());
        QCOMPARE(edited->document().scriptInfo(u8"YCbCr Matrix"), std::optional<std::u8string>(u8"TV.601"));
        // Undo brings the Document's TV.709 back: the source's own matrix again.
        application->editor().discard();
        QVERIFY(QMetaObject::invokeMethod(root, "runGlobalHotkey", Q_ARG(QVariant, QStringLiteral("GLOBAL_UNDO"))));
        QTRY_VERIFY_WITH_TIMEOUT(near(pixel(), bt709), 10000);
        QCOMPARE(session.colourMatrix().applied(), std::string("TV.709"));
    }

    // An untagged HD video is converted with the matrix it is named by,
    // BT.709 (approved departure V4-untagged-matrix: legacy left the
    // converter's BT.601 under the name TV.709 unless the Document said
    // "TV.709", so choosing TV.709 then changed nothing,
    // ProviderFFMS2.cpp:396-412 and 955-962).
    void untaggedHdVideoIsConvertedAsItsMatrix()
    {
        restartWithoutSound();
        QTemporaryDir &folder = testFolder();
        QVERIFY(folder.isValid());
        QFile::copy(QStringLiteral(HIKARI_MEDIA_FIXTURES "/colorhd.mkv"), folder.filePath(QStringLiteral("clip.mkv")));
        QFile f(folder.filePath(QStringLiteral("clip.ass")));
        QVERIFY(f.open(QIODevice::WriteOnly));
        f.write("[Script Info]\nScriptType: v4.00+\nPlayResX: 1280\nPlayResY: 720\nYCbCr Matrix: PC.709\n\n[Events]\n"
                "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n"
                "Dialogue: 0,0:00:00.00,0:00:00.10,Default,,0,0,0,,x\n");
        f.close();
        QVERIFY(application->openFile(f.fileName()));
        application->video().openVideo(folder.filePath(QStringLiteral("clip.mkv")));
        const auto &session = application->video().session();
        QTRY_VERIFY_WITH_TIMEOUT(session.lastFrame(), 20000);
        QCOMPARE(session.colourMatrix().source(), std::string("TV.709"));
        QCOMPARE(session.colourMatrix().applied(), std::string("TV.709"));
        // The fixture's top-left patch (Y' 180, Cb 60, Cr 200, limited range).
        auto pixel = [&] {
            const auto &fr = *session.lastFrame();
            const std::byte *p = fr.bgra.data() + std::size_t(fr.height / 4) * fr.stride + std::size_t(fr.width / 4) * 4;
            return std::array<int, 3>{std::to_integer<int>(p[2]), std::to_integer<int>(p[1]), std::to_integer<int>(p[0])};
        };
        auto expected = [](double kr, double kb) {
            const double y = (180 - 16) / 219.0, pb = (60 - 128) / 224.0, pr = (200 - 128) / 224.0;
            const double r = y + 2 * (1 - kr) * pr, b = y + 2 * (1 - kb) * pb, g = (y - kr * r - kb * b) / (1 - kr - kb);
            auto code = [](double v) { return int(std::lround(std::clamp(v, 0.0, 1.0) * 255)); };
            return std::array<int, 3>{code(r), code(g), code(b)};
        };
        auto near = [](const std::array<int, 3> &a, const std::array<int, 3> &b) {
            for (int k = 0; k < 3; ++k)
                if (std::abs(a[k] - b[k]) > 3)
                    return false;
            return true;
        };
        const auto bt709 = expected(0.2126, 0.0722), bt601 = expected(0.299, 0.114);
        QVERIFY2(near(pixel(), bt709), "the untagged HD frame is converted as BT.709, its name");
        // Script properties: TV.601 converts it as BT.601, TV.709 back as BT.709.
        auto *root = engine->rootObjects().first();
        auto *dialog = root->findChild<QObject *>(QStringLiteral("scriptPropertiesDialog"));
        auto choose = [&](int index, const QString &name) {
            QVERIFY(QMetaObject::invokeMethod(root->findChild<QObject *>(QStringLiteral("assProperties")), "triggered"));
            QTRY_VERIFY(dialog->property("visible").toBool());
            auto *matrix = dialogItem("scriptPropertiesDialog", "propMatrix");
            matrix->setProperty("currentIndex", index);
            QCOMPARE(matrix->property("currentText").toString(), name);
            QVERIFY(QMetaObject::invokeMethod(dialog, "accept"));
            QTRY_VERIFY(!dialog->property("visible").toBool());
        };
        choose(1, QStringLiteral("TV.601"));
        QTRY_VERIFY_WITH_TIMEOUT(near(pixel(), bt601), 10000);
        QCOMPARE(session.colourMatrix().applied(), std::string("TV.601"));
        choose(3, QStringLiteral("TV.709"));
        QTRY_VERIFY_WITH_TIMEOUT(near(pixel(), bt709), 10000);
        QCOMPARE(session.colourMatrix().applied(), std::string("TV.709"));
    }


    // V5 (#184): video fullscreen (VideoBox::SetFullscreen, Fullscreen).
    // Two Lines (0-1 s, 1-2 s) in a file beside its video, the video open.
    bool v5Open(QTemporaryDir &folder)
    {
        if (!QFile::copy(QStringLiteral(HIKARI_MEDIA_FIXTURES "/cfr.mkv"), folder.filePath(QStringLiteral("clip.mkv"))))
            return false;
        // The video's resolution as PlayRes: no "resolution mismatch" question
        // comes up over the window.
        const QString subtitles = folder.filePath(QStringLiteral("clip.ass"));
        QFile f(subtitles);
        if (!f.open(QIODevice::WriteOnly))
            return false;
        f.write("[Script Info]\nScriptType: v4.00+\nPlayResX: 320\nPlayResY: 240\n\n"
                "[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n"
                "Dialogue: 0,0:00:00.00,0:00:01.00,Default,,0,0,0,,first\n"
                "Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,second\n");
        f.close();
        if (!application->openFile(subtitles))
            return false;
        application->video().openVideo(folder.filePath(QStringLiteral("clip.mkv")));
        return QTest::qWaitFor([&] {
            return item("videoPresenter")->property("presentedGeneration").toULongLong() > 0
                   && application->video().session().lastFrame();
        }, 20000);
    }
    QQuickWindow *fullscreenWindow() const { return qobject_cast<QQuickWindow *>(named("videoFullscreen")); }
    QQuickItem *fullscreenItem(const char *name) const
    {
        auto *w = fullscreenWindow();
        return w ? findItem(w->contentItem(), QLatin1String(name)) : nullptr;
    }
    application::EditSession *v5Session() const
    {
        return application->files().session(*application->workspace().editingTarget());
    }

    // F in the Video panel shows the picture fullscreen on the main window's
    // monitor and leaves the main window as it was; the Video window's and
    // the Global bindings work there; Esc leaves, pausing, and gives the
    // keyboard back to what had it.
    void videoFullscreenEnterAndLeave()
    {
        restartWithoutSound();
        QTemporaryDir &folder = testFolder();
        QVERIFY(v5Open(folder));
        keysNeverRepeat();
        auto &fs = application->videoFullscreen();
        QQuickWindow *fsWindow = fullscreenWindow();
        QVERIFY(fsWindow);
        QVERIFY(!fsWindow->isVisible());
        QVERIFY(!fs.active());
        const QRect mainGeometry = window->geometry();
        const auto mainVisibility = window->visibility();
        auto *video = item("videoPanel");
        video->forceActiveFocus();
        // Frame 30 shown before (a frame submitted at the move itself:
        // videoFullscreenPresentsTheFramePendingAtTheMove).
        QVERIFY(application->video().showFrameAt(30));
        QTRY_COMPARE(application->video().session().shownFrame().value_or(-1), 30);
        press(Qt::Key_F);
        QVERIFY(fs.active());
        QTRY_VERIFY(fsWindow->isVisible());
        QCOMPARE(fsWindow->visibility(), QWindow::FullScreen);
        QCOMPARE(fsWindow->screen(), window->screen()); // SetFullscreen(0): the program's monitor
        QTRY_COMPARE(fsWindow->geometry(), fsWindow->screen()->geometry());
        QCOMPARE(fs.monitor(), 0);
        QVERIFY(!fs.onAnotherMonitor());
        QVERIFY(application->videoView().fullscreen());
        // The picture, its overlay and the zoom moved into the window, and
        // frames keep presenting there.
        auto *presenter = item("videoPresenter");
        QCOMPARE(presenter->window(), fsWindow);
        QCOMPARE(item("visualOverlay")->window(), fsWindow);
        // (cfr.mkv's frames move a white block: the picture changes.)
        QTest::qWait(300);
        const QRect picture = item("visualOverlay")->mapRectToScene(application->visualTools().videoRect()).toAlignedRect();
        const QImage before = fsWindow->grabWindow().copy(picture);
        QSignalSpy presented(presenter, SIGNAL(presented()));
        QVERIFY(application->video().stepFrames(12));
        QTRY_VERIFY(presented.count() > 0);
        QTRY_VERIFY(fsWindow->grabWindow().copy(picture) != before);
        // FS1: the bar in Auto (the default) shows on entering, over the
        // picture, which takes the whole window; the hint names Esc, and the
        // file name's strip is up with the bar.
        auto *panel = fullscreenItem("videoFullscreenPanel");
        QCOMPARE(fs.barMode(), 0);
        QVERIFY(!fs.pinned());
        QVERIFY(fs.barShown());
        QTRY_VERIFY(panel && panel->isVisible());
        QTRY_VERIFY(fullscreenItem("videoFullscreenHint")->isVisible());
        QCOMPARE(fullscreenItem("videoFullscreenHintText")->property("text").toString(),
                 QStringLiteral("Press Esc to exit full screen"));
        QTRY_VERIFY(fullscreenItem("videoFullscreenTitle")->isVisible());
        QTRY_COMPARE(presenter->height(), qreal(fsWindow->height()));
        QCOMPARE(presenter->width(), qreal(fsWindow->width()));
        // No tool on: no rail, no tool row.
        QVERIFY(!fullscreenItem("fullscreenToolRail")->isVisible());
        QVERIFY(!fullscreenItem("fullscreenInspectorSlot")->isVisible());
        // The 4:3 picture fills the stage's width or height, centred.
        const QRectF shownRect = application->visualTools().videoRect();
        QVERIFY(qAbs(shownRect.width() - presenter->width()) <= 1 || qAbs(shownRect.height() - presenter->height()) <= 1);
        QVERIFY(qAbs(shownRect.center().x() - presenter->width() / 2) <= 1);
        QVERIFY(qAbs(shownRect.center().y() - presenter->height() / 2) <= 1);
        // The transport's icon-only buttons name themselves.
        for (const char *name : {"fullscreenPreviousFile", "fullscreenPlayPause", "fullscreenPlayLine", "fullscreenStop",
                                 "fullscreenNextFile", "fullscreenOpenEditor", "fullscreenToolsButton", "fullscreenSpeaker",
                                 "fullscreenExit"}) {
            auto *button = fullscreenItem(name);
            QVERIFY2(button && button->isVisible(), name);
            QCOMPARE(button->property("display").toInt(), 0); // AbstractButton.IconOnly
            QVERIFY2(!QAccessible::queryAccessibleInterface(button)->text(QAccessible::Name).isEmpty(), name);
            QVERIFY2(!button->property("tip").toString().isEmpty(), name);
        }
        QCOMPARE(fullscreenItem("fullscreenExit")->property("tip").toString(), QStringLiteral("Exit full screen (Escape)"));
        // The mode button names the mode; its tooltip the binding (Tab).
        QCOMPARE(fullscreenItem("fullscreenBarMode")->property("text").toString(), QStringLiteral("Auto"));
        QVERIFY(fullscreenItem("fullscreenBarMode")->property("tip").toString().startsWith(QStringLiteral("Full screen bar (Tab)")));
        QCOMPARE(fullscreenItem("fullscreenVideoName")->property("text").toString(), QStringLiteral("clip.mkv"));
        // FS1-current-line: the first Line, read only.
        QTRY_VERIFY(fullscreenItem("fullscreenLine")->isVisible());
        QCOMPARE(fullscreenItem("fullscreenLineNumber")->property("text").toString(), QStringLiteral("1"));
        QCOMPARE(fullscreenItem("fullscreenLineText")->property("text").toString(), QStringLiteral("first"));
        QCOMPARE(fullscreenItem("fullscreenLineTimes")->property("text").toString(),
                 application->editor().startText() + QStringLiteral(" – ") + application->editor().endText());
        // The Line editor's draft, as the video shows it, not the stored text.
        application->editor().textEdited(QStringLiteral("{\\i1}draft\\Nnow"), 5);
        QTRY_COMPARE(fullscreenItem("fullscreenLineText")->property("text").toString(), QStringLiteral("draft \u21B5 now"));
        // Markup in a Line (and a file's name) is text: nothing parsed, no
        // <img> fetched.
        const QString markup = QStringLiteral("<img src=\"http://127.0.0.1:9/x\"><b>bold</b>");
        application->editor().textEdited(markup, int(markup.size()));
        QTRY_COMPARE(fullscreenItem("fullscreenLineText")->property("text").toString(), markup);
        QCOMPARE(fullscreenItem("fullscreenLineText")->property("textFormat").toInt(), int(Qt::PlainText));
        QCOMPARE(fullscreenItem("fullscreenVideoName")->property("textFormat").toInt(), int(Qt::PlainText));
        application->editor().discard();
        QTRY_COMPARE(fullscreenItem("fullscreenLineText")->property("text").toString(), QStringLiteral("first"));
        // The progress bar's times (VIDEO_PROGRESS_BAR is on by default).
        auto *progress = fullscreenItem("videoFullscreenProgress");
        QVERIFY(progress->isVisible());
        QCOMPARE(fullscreenItem("videoFullscreenProgressText")->property("text").toString(),
                 QStringLiteral("00:00:01 / 00:00:01")); // frame 42 at 1.75 s; LastTime 1.96 s, truncated
        auto *bar = fullscreenItem("videoFullscreenProgressBar");
        QVERIFY(bar->x() + bar->width() <= fsWindow->width());
        // The window takes the keyboard: Space (the Video window's
        // VIDEO_PLAY_PAUSE) plays and pauses, Right (the Global
        // GLOBAL_NEXT_FRAME) steps.
        QVERIFY(becomesFocusWindow(fsWindow));
        QVERIFY(application->hotkeys().accelOf(QStringLiteral("VIDEO_PLAY_PAUSE"), 3) == QStringLiteral("Space"));
        QTest::keyClick(fsWindow, Qt::Key_Space);
        QTRY_VERIFY(application->video().playing());
        QTest::keyClick(fsWindow, Qt::Key_Space);
        QTRY_VERIFY(!application->video().playing());
        const int frame = application->video().frame();
        QTest::keyClick(fsWindow, Qt::Key_Right);
        QTRY_COMPARE(application->video().frame(), frame + 1);
        // Leaving while playing pauses (the editor is always on).
        QTest::keyClick(fsWindow, Qt::Key_Space);
        QTRY_VERIFY(application->video().playing());
        QTest::keyClick(fsWindow, Qt::Key_Escape);
        QVERIFY(!fs.active());
        QVERIFY(!application->video().playing());
        QTRY_VERIFY(!fsWindow->isVisible());
        QCOMPARE(presenter->window(), window);
        QVERIFY(!application->videoView().fullscreen());
        QCOMPARE(window->geometry(), mainGeometry);
        QCOMPARE(window->visibility(), mainVisibility);
        QVERIFY(becomesFocusWindow(window));
        QTRY_COMPARE(window->activeFocusItem(), video);
        // The picture is the panel's again.
        QTRY_COMPARE(presenter->width(), item("videoStage")->parentItem()->width());

        // From the Line editor through VIDEO_FULL_SCREEN (unbound by
        // default): the Line editor has the keyboard back after B.
        auto *lineText = item("lineText");
        lineText->forceActiveFocus();
        auto *root = engine->rootObjects().first();
        QVERIFY(QMetaObject::invokeMethod(root, "runVideoHotkey", Q_ARG(QVariant, QStringLiteral("VIDEO_FULL_SCREEN"))));
        QVERIFY(fs.active());
        QVERIFY(becomesFocusWindow(fsWindow));
        QTest::keyClick(fsWindow, Qt::Key_B);
        QVERIFY(!fs.active());
        QVERIFY(becomesFocusWindow(window));
        QTRY_COMPARE(window->activeFocusItem(), lineText);
        // F in the fullscreen window leaves too.
        video->forceActiveFocus();
        press(Qt::Key_F);
        QVERIFY(fs.active());
        QVERIFY(becomesFocusWindow(fsWindow));
        QTest::keyClick(fsWindow, Qt::Key_F);
        QVERIFY(!fs.active());
        // Without a video nothing happens (`if (!renderer) return`).
        QVERIFY(application->video().unloadVideo());
        video->forceActiveFocus();
        press(Qt::Key_F);
        QVERIFY(!fs.active());
        QVERIFY(!fsWindow->isVisible());
    }

    // The context menu in fullscreen: "Exit full screen", "Open editor" and
